BEGIN READ ONLY;
SELECT json_build_object('kind','columns','rows',(SELECT json_agg(x ORDER BY table_name,ordinal_position) FROM (SELECT table_name,ordinal_position,column_name,data_type,udt_name,is_nullable,column_default FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('seller_agents','seller_profiles','locations','businesses','properties','organizations')) x));
SELECT json_build_object('kind','constraints','rows',(SELECT json_agg(x ORDER BY tbl,name) FROM (SELECT c.relname tbl,co.conname name,co.convalidated validated,pg_get_constraintdef(co.oid) definition FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('seller_agents','seller_profiles','locations','businesses','properties','organizations')) x));
SELECT json_build_object('kind','indexes','rows',(SELECT json_agg(x ORDER BY tablename,indexname) FROM (SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='public' AND tablename IN ('seller_agents','seller_profiles','locations','businesses','properties','organizations')) x));
SELECT json_build_object('kind','triggers','rows',(SELECT json_agg(x ORDER BY tbl,name) FROM (SELECT c.relname tbl,t.tgname name,t.tgenabled enabled,pg_get_triggerdef(t.oid) definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND c.relname IN ('seller_agents','seller_profiles','locations','businesses','properties','organizations')) x));
SELECT json_build_object('kind','functions','rows',(SELECT json_agg(x ORDER BY name,args) FROM (SELECT p.proname name,pg_get_function_identity_arguments(p.oid) args,p.prosecdef security_definer,p.provolatile volatility,p.proconfig config,pg_get_functiondef(p.oid) definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('seller_agents_check_chain','seller_profiles_link_agent','seller_agent_ensure','seller_agents_backfill','seller_agent_bind_location','seller_scope_assert','seller_scope_precheck')) x));
SELECT json_build_object('kind','policies','rows',(SELECT json_agg(x ORDER BY tablename,policyname) FROM (SELECT tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename IN ('seller_agents','seller_profiles','locations','businesses','properties','organizations')) x));
SELECT json_build_object('kind','rls','rows',(SELECT json_agg(x ORDER BY name) FROM (SELECT c.relname name,c.relrowsecurity enabled,c.relforcerowsecurity forced FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('seller_agents','seller_profiles','locations','businesses','properties','organizations')) x));
SELECT json_build_object('kind','grants','rows',(SELECT json_agg(x ORDER BY table_name,grantee,privilege_type) FROM (SELECT table_name,grantee,privilege_type FROM information_schema.role_table_grants WHERE table_schema='public' AND table_name IN ('seller_agents','seller_profiles','locations','businesses','properties','organizations') AND grantee IN ('wetop_app','anon','authenticated','PUBLIC')) x));
COMMIT;
